package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.io.*;import java.util.*;import com.google.gson.*;
class Us01AssetTest{
 static final Path DIR=Path.of("src/main/resources/assets/sbwdroneconfig/us01");
 @Test void originalGeometryIsPartitionedExactlyOnceWithNoReferenceBody()throws Exception{var j=JsonParser.parseString(Files.readString(DIR.resolve("us01.json"))).getAsJsonObject();for(String v:List.of("classic","slim")){var m=j.getAsJsonObject(v);assertTrue(m.get("model").getAsString().endsWith("REV02"));assertEquals(607,m.get("armorMeshes").getAsInt());assertEquals(6,m.get("referencesExcluded").getAsInt());assertEquals(13818,m.get("triangles").getAsInt());var names=new HashSet<String>();for(var n:m.getAsJsonArray("meshes")){var e=n.getAsJsonObject();String name=e.get("name").getAsString();assertFalse(name.startsWith("REF_"));assertFalse(name.toLowerCase().matches(".*(goggle|eyewear|glasses|lens).*"));assertTrue(names.add(name));}assertEquals(607,names.size());}}
 @Test void binariesHaveExpectedBodyBindingsFiniteVerticesAndOriginalFaceCount()throws Exception{int[]expected={2738,6744,1360,2976};String[]slots={"head","chest","legs","feet"};for(String v:List.of("classic","slim"))for(int slot=0;slot<4;slot++)try(var in=new DataInputStream(Files.newInputStream(DIR.resolve(slots[slot]+"_"+v+".bin")))){assertEquals(0x55533031,in.readInt());int count=in.readInt(),total=0;assertTrue(count>0&&count<=6);for(int i=0;i<count;i++){int limb=in.readInt(),option=in.readInt(),faces=in.readInt();assertTrue(switch(slot){case 0->limb==0;case 1->limb>=1&&limb<=3;case 2->limb==1||limb>=4&&limb<=5;default->limb>=4&&limb<=5;});assertTrue(option>=0&&option<=3);total+=faces;for(int f=0;f<faces;f++){float[]a=new float[23];for(int k=0;k<23;k++){a[k]=in.readFloat();assertTrue(Float.isFinite(a[k]));}assertEquals(1,Math.sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]),1e-5);for(int k=3;k<23;k+=5){assertTrue(a[k+3]>=0&&a[k+3]<=1);assertTrue(a[k+4]>=0&&a[k+4]<=1);}}}assertEquals(expected[slot],total);assertEquals(-1,in.read());}}
 @Test void atlasPreservesAllOriginalTexturePixelsWithoutTheExampleSkin()throws Exception{var atlas=javax.imageio.ImageIO.read(DIR.resolve("us01_atlas.png").toFile());assertEquals(4096,atlas.getWidth());assertEquals(2048,atlas.getHeight());int[][]offsets={{2048,1024},{0,0},{2048,0},{3072,0}};String[]files={"US01_Materials.png","US01_Organic_Camo_2048.png","US01_Textiles_1024.png","US01_Details_1024.png"};for(int i=0;i<4;i++){var original=javax.imageio.ImageIO.read(Path.of("model_sources/us01/"+files[i]).toFile());int w=original.getWidth(),h=original.getHeight();assertArrayEquals(original.getRGB(0,0,w,h,null,0,w),atlas.getRGB(offsets[i][0],offsets[i][1],w,h,null,0,w));}assertFalse(Files.exists(DIR.resolve("US01_Example_Skin_REFERENCE_ONLY.png")));}
 @Test void classicSlimAndOuterArmFlagsRetainTheirApprovedDifferences()throws Exception{var j=JsonParser.parseString(Files.readString(DIR.resolve("us01.json"))).getAsJsonObject();for(String v:List.of("classic","slim")){var flags=j.getAsJsonObject(v).getAsJsonObject("flags");assertEquals(2,flags.size());for(var flag:flags.entrySet())for(var n:flag.getValue().getAsJsonArray())assertTrue(flag.getKey().startsWith("right")?n.getAsJsonArray().get(0).getAsFloat()<-.99:n.getAsJsonArray().get(0).getAsFloat()>.99);}for(String slot:List.of("head","legs","feet"))assertArrayEquals(Files.readAllBytes(DIR.resolve(slot+"_classic.bin")),Files.readAllBytes(DIR.resolve(slot+"_slim.bin")));assertFalse(Arrays.equals(Files.readAllBytes(DIR.resolve("chest_classic.bin")),Files.readAllBytes(DIR.resolve("chest_slim.bin"))));}
}
